CLASS_WEIGHT = {"dead": 1.0, "degraded": 1.0, "cosmetic": 0.1}

def weighted_q(checks):
    total = sum(CLASS_WEIGHT[c.kind] for c in checks)
    return sum(CLASS_WEIGHT[c.kind] * c.score for c in checks) / total

def failed_checks(checks):
    # Cosmetic misses affect Q but do not select a reward band.
    return [c.kind for c in checks if not c.passed and c.kind in {"dead", "degraded"}]

def reward(q, failed):
    if not failed: return 0.50 + 0.50 * q
    if "dead" in failed: return 0.01 + 0.24 * q
    return 0.25 + 0.25 * q

def reward_for_checks(q, checks):
    return reward(q, failed_checks(checks))

